class Solution:
    def minMoves(self, nums: List[int], k: int, maxChanges: int) -> int:
        pos = [i for i, v in enumerate(nums) if v]
        n = len(pos)
        pre = [0] * (n + 1)
        for i, x in enumerate(pos):
            pre[i + 1] = pre[i] + x
        def win(i, j):
            m = (i + j) // 2; md = pos[m]
            return (md * (m - i) - (pre[m] - pre[i])) + ((pre[j + 1] - pre[m + 1]) - md * (j - m))
        c = min(maxChanges, k); need = k - c
        ans = float('inf')
        if need == 0:
            ans = 2 * k
        for sz in (need, need + 1):
            if sz < 1 or sz > n:
                continue
            for i in range(n - sz + 1):
                ans = min(ans, win(i, i + sz - 1) + 2 * (k - sz))
        return ans

