class Solution {
public:
    long long minMoves(vector<int>& nums, int k, int maxChanges) {
        vector<long long> pos;
        for (int i = 0; i < (int)nums.size(); i++) if (nums[i]) pos.push_back(i);
        int n = pos.size();
        vector<long long> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + pos[i];
        auto win = [&](int i, int j) {
            int m = (i + j) / 2; long long md = pos[m];
            return md * (m - i) - (pre[m] - pre[i]) + (pre[j + 1] - pre[m + 1]) - md * (j - m);
        };
        int c = min(maxChanges, k), need = k - c;
        long long ans = LLONG_MAX;
        if (need == 0) ans = 2LL * k;
        int sizes[2] = {need, need + 1};
        for (int t = 0; t < 2; t++) {
            int sz = sizes[t];
            if (sz < 1 || sz > n) continue;
            for (int i = 0; i + sz <= n; i++)
                ans = min(ans, win(i, i + sz - 1) + 2LL * (k - sz));
        }
        return ans;
    }
};

