class Solution {
    public long minMoves(int[] nums, int k, int maxChanges) {
        List<Long> pos = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) if (nums[i] == 1) pos.add((long) i);
        int n = pos.size();
        long[] pre = new long[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + pos.get(i);
        java.util.function.LongBinaryOperator unused = null;
        long ans = Long.MAX_VALUE;
        int c = Math.min(maxChanges, k), need = k - c;
        if (need == 0) ans = 2L * k;
        int[] sizes = {need, need + 1};
        for (int sz : sizes) {
            if (sz < 1 || sz > n) continue;
            for (int i = 0; i + sz <= n; i++) {
                int j = i + sz - 1, m = (i + j) / 2;
                long md = pos.get(m);
                long cost = md * (m - i) - (pre[m] - pre[i]) + (pre[j + 1] - pre[m + 1]) - md * (j - m);
                ans = Math.min(ans, cost + 2L * (k - sz));
            }
        }
        return ans;
    }
}

