var minMoves = function(nums, k, maxChanges) {
    const pos = [];
    for (let i = 0; i < nums.length; i++) if (nums[i] === 1) pos.push(i);
    const n = pos.length;
    const pre = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pre[i + 1] = pre[i] + pos[i];
    const win = (i, j) => {
        const m = (i + j) >> 1, md = pos[m];
        return md * (m - i) - (pre[m] - pre[i]) + (pre[j + 1] - pre[m + 1]) - md * (j - m);
    };
    const c = Math.min(maxChanges, k), need = k - c;
    let ans = Infinity;
    if (need === 0) ans = 2 * k;
    for (const sz of [need, need + 1]) {
        if (sz < 1 || sz > n) continue;
        for (let i = 0; i + sz <= n; i++)
            ans = Math.min(ans, win(i, i + sz - 1) + 2 * (k - sz));
    }
    return ans;
};
